/// Server-push snapshots with a bounded lease; no per-client progress polling.
#[tauri::command]
pub async fn watch_downloads(state: State<'_, AppState>, on_update: tauri::ipc::Channel<serde_json::Value>) -> Result<(),String> {
    use std::time::Duration;
    let _lease=state.downloads.subscriptions.try_acquire().map_err(|_|"Too many download subscriptions")?;
    let mut changes=state.downloads.subscribe();
    let deadline=tokio::time::Instant::now()+Duration::from_secs(30);
    loop {
        let _=*changes.borrow_and_update();
        let snapshot={
            let data=state.downloads.lock().map_err(|_|"Download registry poisoned")?;
            if data.len()>4096 {return Err("Download registry limit exceeded".into());}
            serde_json::to_value(&*data).map_err(|e|e.to_string())?
        };
        if on_update.send(snapshot).is_err(){return Ok(());}
        match tokio::time::timeout_at(deadline,changes.changed()).await {
            Ok(Ok(()))=>{},
            _=>return Ok(()),
        }
        tokio::time::sleep(Duration::from_millis(250)).await;
        if tokio::time::Instant::now()>=deadline{return Ok(());}
    }
}

